const taskCopy={zh:{image_creation:{label:'已选择：图像创作',prompt:'你想创作什么图片或海报？',guide:'目前 AI 可以帮你准备详细的图像提示词、风格方向和构图。'},writing:{label:'已选择：写作与方案',prompt:'你想写什么或规划什么？',guide:'说出你的目标，AI 会帮你整理内容与方案。'},presentation:{label:'已选择：演示文稿',prompt:'你想制作什么样的演示文稿？',guide:'目前 AI 可以准备 PPT 大纲与逐页内容。'},video:{label:'已选择：视频与音频',prompt:'你想制作什么视频或音频内容？',guide:'目前 AI 可以准备脚本、分镜和制作提示词。'},productivity:{label:'已选择：效率与办公',prompt:'你想完成什么工作？',guide:'说出目标，AI 会帮你规划下一步。'}},en:{image_creation:{label:'Selected: Image creation',prompt:'What image or poster would you like to create?',guide:'AI can currently prepare a detailed image prompt, style direction, and composition.'},writing:{label:'Selected: Writing & plans',prompt:'What would you like to write or plan?',guide:'Tell us your goal and AI will help shape the content and plan.'},presentation:{label:'Selected: Presentations',prompt:'What presentation would you like to create?',guide:'AI can currently prepare a slide outline and slide-by-slide content.'},video:{label:'Selected: Video & audio',prompt:'What video or audio would you like to create?',guide:'AI can currently prepare a script, storyboard, and production prompt.'},productivity:{label:'Selected: Work & productivity',prompt:'What would you like help accomplishing?',guide:'Tell us the goal and AI will help plan the next steps.'}}};
const search=document.querySelector('#toolSearch'),cards=[...document.querySelectorAll('.tool-card')],empty=document.querySelector('#emptyState'),toast=document.querySelector('#toast'),toggle=document.querySelector('#languageToggle'),taskGuide=document.querySelector('#taskGuide');let timer,lang,activeTask='';
function toastMsg(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>toast.classList.remove('show'),2600)}
function renderTaskGuide(){if(!activeTask){taskGuide.hidden=true;taskGuide.textContent='';return}const task=taskCopy[lang][activeTask];taskGuide.textContent=`${task.label} · ${task.guide}`;taskGuide.hidden=false}
function applyLanguage(next){lang=next;const t=copy[lang];document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=lang==='zh'?'AI SuperMall — 让想法即刻发生':'AI SuperMall — Make ideas happen';document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t[el.dataset.i18n]);document.querySelectorAll('[data-i18n-html]').forEach(el=>el.innerHTML=t[el.dataset.i18nHtml]);document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>el.placeholder=t[el.dataset.i18nPlaceholder]);document.querySelectorAll('[data-i18n-query]').forEach(el=>el.dataset.query=t[el.dataset.i18nQuery]);cards.forEach((card,i)=>card.dataset.tags=t.tags[i]);toggle.textContent=lang==='zh'?'EN':'中文';toggle.setAttribute('aria-label',lang==='zh'?'Switch to English':'切换至中文');const voice=document.querySelector('#voiceButton');if(voice){voice.setAttribute('aria-label',lang==='zh'?'语音输入':'Voice input');voice.title=lang==='zh'?'语音输入':'Voice input'}if(activeTask)search.placeholder=taskCopy[lang][activeTask].prompt;renderTaskGuide();localStorage.setItem('ai-supermall-language',lang)}
function filterTools(q){const term=q.trim().toLowerCase();let visible=0;cards.forEach(card=>{const match=!term||(`${card.dataset.tags} ${card.textContent}`).toLowerCase().includes(term);card.hidden=!match;if(match)visible++});empty.hidden=visible>0;document.querySelector('#discover').scrollIntoView({behavior:'smooth',block:'start'});if(term&&visible)toastMsg(copy[lang].found(visible))}
const stored=localStorage.getItem('ai-supermall-language');const china=['Asia/Shanghai','Asia/Urumqi','Asia/Chongqing','Asia/Harbin'].includes(Intl.DateTimeFormat().resolvedOptions().timeZone);applyLanguage(stored||(china?'zh':'en'));toggle.addEventListener('click',()=>applyLanguage(lang==='zh'?'en':'zh'));
function clearTask(){activeTask='';search.placeholder=copy[lang].searchPlaceholder;renderTaskGuide()}
function workspaceForIntent(text){const value=String(text||'');if(/海报|图片|图像|改图|修图|视觉|照片|photo|poster|image|visual/i.test(value))return'visual';if(/视频|短片|剪辑|配音|video|short/i.test(value))return'video';if(/演示文稿|幻灯片|汇报|ppt|presentation|slides/i.test(value))return'presentation';if(/写作|文章|文案|改写|润色|写一篇|writing|article|copywriting|rewrite/i.test(value))return'writing';return''}
function projectIntent(){if(conversation.some(item=>item?.workspace==='presentation'||item?.presentation?.slides?.length))return'presentation';if(conversation.some(item=>item?.workspace==='writing'))return'writing';return workspaceForIntent(conversation.map(item=>`${item.question||''}\n${item.answer||''}`).join('\n'))||'knowledge'}
function projectConversation(){const workspace=projectIntent();return[{type:'project_meta',workspace,intent:workspace,task:String(conversation.at(-1)?.question||conversation[0]?.question||'').slice(0,2000)},...conversation]}
function openWorkspace(workspace,task=''){const safeTask=String(task||'').trim().slice(0,2000);if(safeTask)sessionStorage.setItem('ai-supermall-workspace-handoff',JSON.stringify({workspace,task:safeTask,language:lang}));else sessionStorage.removeItem('ai-supermall-workspace-handoff');location.href=`create-${workspace}.html?new=1${safeTask?'&handoff=1':''}`}
function startTask(task){if(!taskCopy[lang][task])return;const workspace={image_creation:'visual',writing:'writing',presentation:'presentation',video:'video'}[task];if(workspace){openWorkspace(workspace,taskCopy[lang][task].prompt);return}activeTask=task;renderTaskGuide();search.value='';search.placeholder=taskCopy[lang][task].prompt;document.querySelector('#top').scrollIntoView({behavior:'smooth',block:'start'});setTimeout(()=>search.focus(),250)}
async function updateAccountNavigation(){try{const response=await fetch('/api/account/me');const signedIn=response.ok;const signIn=document.querySelector('#signInLink'),register=document.querySelector('#registerLink');if(signedIn){signIn.href='account.html';signIn.dataset.i18n='navMyAccount';signIn.textContent=copy[lang].navMyAccount;register.hidden=true}else{signIn.href='account.html?mode=login';signIn.dataset.i18n='navSignIn';signIn.textContent=copy[lang].navSignIn;register.hidden=false;register.textContent=copy[lang].navRegister}}catch{}}
updateAccountNavigation();
const answer=document.querySelector('#searchAnswer'),kicker=document.querySelector('#answerKicker'),title=document.querySelector('#answerTitle'),answerCopy=document.querySelector('#answerCopy'),recommendation=document.querySelector('#answerRecommendation'),answerAction=document.querySelector('#answerAction'),projectHistory=document.querySelector('#projectHistory'),followForm=document.querySelector('#followUpForm'),followInput=document.querySelector('#followUpInput'),followLabel=document.querySelector('#followUpLabel'),followSubmit=document.querySelector('#followUpSubmit'),followVoice=document.querySelector('#followUpVoice'),mainSubmit=document.querySelector('#searchForm button[type="submit"]');let conversation=[],lastAnswerLanguage='zh',activeProjectId='',activeProjectTitle='';
const answerLanguageFor=q=>/[\u4e00-\u9fff]/.test(q)?'zh':'en';
function setFollowLanguage(language){const zh=language==='zh';followLabel.textContent=zh?'继续追问':'Continue the conversation';followInput.placeholder=zh?'输入你的下一句问题…':'Type your next question…';followSubmit.textContent=zh?'发送':'Next';followVoice.setAttribute('aria-label',zh?'语音输入':'Voice input')}
async function askAi(query,input,language){lastAnswerLanguage=language;answer.hidden=false;kicker.textContent='AI SUPERMALL · AI';title.textContent=language==='zh'?'正在思考…':'Thinking…';answerCopy.textContent=language==='zh'?'正在为你准备回答。':'Preparing your answer.';recommendation.textContent='';answerAction.hidden=true;followForm.hidden=!conversation.length;input.disabled=true;mainSubmit.disabled=true;try{const response=await fetch('/api/recommend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query,language,context:conversation.slice(-4),taskType:activeTask||'general'})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed');conversation.push({question:query,answer:result.answer||''});title.textContent=language==='zh'?'对话继续中':'Conversation continues';answerCopy.textContent=language==='zh'?'以下保留了你的完整对话。':'Your complete conversation is kept below.';recommendation.textContent=result.recommendation||'';renderProjectHistory(conversation);document.querySelector('#saveConversation').hidden=false;followForm.hidden=false;setFollowLanguage(language);if(activeProjectId)await scheduleProjectSave()}catch(error){title.textContent=language==='zh'?'暂时无法回答':'Unable to answer right now';answerCopy.textContent=language==='zh'?'请稍后再试。':'Please try again shortly.';recommendation.textContent='';answerAction.hidden=true}finally{input.disabled=false;mainSubmit.disabled=false;const latest=projectHistory.lastElementChild;if(activeProjectId||activeConversationId){(latest||answer).scrollIntoView({behavior:'smooth',block:'nearest'})}else{answer.scrollIntoView({behavior:'smooth',block:'center'})}}}
const goToRecommendation=event=>{event.preventDefault();const query=search.value.trim();if(!query){toastMsg(lang==='zh'?'请先输入问题。':'Please enter a question.');search.focus();return}const workspace=workspaceForIntent(query);if(workspace){const carried=[...conversation.slice(-3).map(item=>item.question),query].filter(Boolean).join('\n');openWorkspace(workspace,carried);return}askAi(query,search,answerLanguageFor(query))};
document.querySelector('#searchForm').addEventListener('submit',goToRecommendation);
document.querySelector('#searchForm button[type="submit"]').addEventListener('click',goToRecommendation);
answerAction.addEventListener('click',event=>{event.preventDefault();followForm.hidden=false;setFollowLanguage(lastAnswerLanguage);followInput.focus()});
followForm.addEventListener('submit',event=>{event.preventDefault();const query=followInput.value.trim();if(!query){followInput.setCustomValidity(lastAnswerLanguage==='zh'?'请输入下一句问题。':'Please enter your next question.');followInput.reportValidity();followInput.setCustomValidity('');return}askAi(query,followInput,answerLanguageFor(query));followInput.value=''});
const voiceButton=document.querySelector('#voiceButton');
const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
if(!SpeechRecognition){voiceButton.hidden=true;}else{const recognition=new SpeechRecognition();recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onstart=()=>{voiceButton.classList.add('listening');toastMsg(lang==='zh'?'正在听，请说话…':'Listening…')};recognition.onend=()=>voiceButton.classList.remove('listening');recognition.onerror=()=>toastMsg(lang==='zh'?'没有听清，请再试一次。':'I did not catch that. Please try again.');recognition.onresult=e=>{search.value=e.results[0][0].transcript;toastMsg(lang==='zh'?'已输入语音内容，请点击开始。':'Voice input added. Tap Start.');search.focus()};voiceButton.onclick=()=>{recognition.lang=lang==='zh'?'zh-CN':'en-US';recognition.start()};}
document.querySelectorAll('[data-query]').forEach(btn=>btn.addEventListener('click',()=>{search.value=btn.dataset.query;search.focus()}));document.querySelectorAll('[data-scroll]').forEach(btn=>btn.addEventListener('click',()=>document.querySelector(btn.dataset.scroll).scrollIntoView({behavior:'smooth'})));document.querySelectorAll('.task-entry').forEach(entry=>entry.addEventListener('click',()=>startTask(entry.dataset.task)));document.querySelectorAll('.workspace-entry').forEach(entry=>{const open=()=>openWorkspace(entry.dataset.workspace);entry.addEventListener('click',open);entry.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}})});document.querySelectorAll('a[href="index.html"],[data-mobile-destination="home"]').forEach(link=>link.addEventListener('click',clearTask));
if(!SpeechRecognition){followVoice.hidden=true}else{const followRecognition=new SpeechRecognition();followRecognition.interimResults=false;followRecognition.maxAlternatives=1;followRecognition.onresult=e=>{followInput.value=e.results[0][0].transcript;followInput.focus()};followRecognition.onerror=()=>toastMsg(lastAnswerLanguage==='zh'?'没有听清，请再试一次。':'I did not catch that. Please try again.');followVoice.addEventListener('click',()=>{followRecognition.lang=lastAnswerLanguage==='zh'?'zh-CN':'en-US';followRecognition.start()})}
