function renderProjectHistory(items){projectHistory.innerHTML='';items.forEach(item=>{const card=document.createElement('div'),question=document.createElement('strong'),answerText=document.createElement('p');question.textContent=item.question||'';answerText.className='project-answer';answerText.textContent=item.answer||'';card.append(question,answerText);projectHistory.append(card)});projectHistory.hidden=!items.length}
